// Import of required libraries
import { test, expect, getBaseUrl, newSkyrampPlaywrightPage } from '@skyramp/skyramp';

const pageTimeout = 15000;

// URL for test requests
const baseUrl = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:3000");

test.use({
    viewport: { width: 1280, height: 900 },
});

test('testUi', async ({ page }) => {
    test.setTimeout(381000);

    // set default timeout for all locator/page actions in this test
    page.setDefaultTimeout(pageTimeout);
    // Wrap playwright page with Skyramp page
    page = newSkyrampPlaywrightPage(page);

    await page.goto(baseUrl);
    await page.waitForLoadState('networkidle');

    // seed two library items
    await page.getByTestId("toolbar-rectangle").click({ force: true });
    await page.mouse.move(400, 300);
    await page.mouse.down();
    await page.mouse.move(540, 410, { steps: 10 });
    await page.mouse.up();
    await page.getByRole("checkbox", { name: "Library" }).click({ force: true });
    await page.locator("div.library-unit__dragger").first().click();

    await page.getByTestId("toolbar-ellipse").click({ force: true });
    await page.mouse.move(650, 300);
    await page.mouse.down();
    await page.mouse.move(780, 410, { steps: 10 });
    await page.mouse.up();
    await page.getByRole("checkbox", { name: "Library" }).click({ force: true });
    await page.locator("div.library-unit__dragger").first().click();
    await expect(page.getByTestId("library").locator("div.library-unit")).toHaveCount(2);

    // select exactly one item -> the itemsSelected branch
    await page.getByTestId("library").getByRole("checkbox").first().click({ force: true });

    await page.getByTestId("library").getByTestId("dropdown-menu-button").click();

    // with a selection the destructive action is "Remove", never "Reset library"
    await expect(page.getByTestId("dropdown-menu").getByRole("menuitem", { name: "Remove" })).toBeVisible();
    await expect(page.getByTestId("dropdown-menu").getByRole("menuitem", { name: "Reset library" })).toHaveCount(0);
    await page.getByTestId("dropdown-menu").getByRole("menuitem", { name: "Remove" }).click();

    // the legacy per-selection dialog must open, NOT the shared reset-all dialog
    await expect(page.getByText("Delete 1 item(s) from library?")).toBeVisible();
    await expect(page.getByText("This will clear your library. Are you sure?")).toHaveCount(0);

    await page.getByRole("button", { name: "Confirm" }).click();

    // only the selected item is deleted; the library is not wiped
    await expect(page.getByTestId("library").locator("div.library-unit")).toHaveCount(1);
    await expect(page.getByText("No items added yet...")).toHaveCount(0);
});
